use vstd::prelude::*;

verus! {
    // Iteratively reverse a non‐empty vector of chars.
    // Requires: input vector has length > 0.
    // Ensures: the result has the same length as the input,
    // and for all valid k, result[k] == a[a.len() - 1 - k].
    fn reverse(a: &Vec<char>) -> (res: Vec<char>)
        requires
            a.len() > 0,
        ensures
            res.len() == a.len(),
            forall |k: usize| k < res.len() ==> res[k] == a[a.len() - 1 - k],
    {
        let n = a.len();
        // We'll build up the result in 'res', one element at a time.
        let mut res: Vec<char> = Vec::new();
        res.reserve(n);

        let mut i: usize = 0;
        while i < n
            invariant
                // i never exceeds n
                i <= n,
                // res.len() equals the number of iterations so far
                res.len() == i,
                // and for all positions < i, we've established the correct reverse property
                forall |k: usize| k < i ==> res[k] == a[n - 1 - k],
            decreases n - i,
        {
            // compute the index in 'a' of the next character to push
            let idx: usize = n - 1 - i;
            // ensure safe indexing
            assert(idx < n);
            let c = a[idx];
            res.push(c);
            i += 1;
        }

        // At this point i == n and res.len() == n,
        // and by the loop invariant res[k] == a[n - 1 - k] for all k < n,
        // which exactly matches our postcondition.
        res
    }
}

